// Custom Worker entry: wraps the OpenNext worker (built into .open-next/) so this Worker can
// also host the LiveRoom Durable Object and route live-room WebSockets to it.
// @ts-ignore: generated by `opennextjs-cloudflare build`
import { default as nextWorker } from './.open-next/worker.js'

export { LiveRoom } from './src/realtime/live-room'

const LIVE_WS = /^\/api\/live\/([^/]+)\/ws$/

export default {
  async fetch(request: Request, env: CloudflareEnv, ctx: ExecutionContext): Promise<Response> {
    const url = new URL(request.url)
    const match = url.pathname.match(LIVE_WS)
    if (match) {
      const streamId = decodeURIComponent(match[1])
      const room = env.LIVE_ROOM.get(env.LIVE_ROOM.idFromName(streamId))
      const target = new URL('https://live-room/ws')
      target.searchParams.set('stream', streamId)
      const ticket = url.searchParams.get('ticket')
      if (ticket) target.searchParams.set('ticket', ticket)
      return room.fetch(new Request(target, request))
    }
    return nextWorker.fetch(request, env, ctx)
  },
} satisfies ExportedHandler<CloudflareEnv>
